INSERT /* homes.batch.mapper.BatchMapper.insertBaseSummry 기본개요 등록 */
INTO   TB_BD_BASESUMMRY_ORIGIN (
	   MNGR_REGSTR_PK, UPPER_REGSTR_PK, REGSTR_GB_CD, REGSTR_GB_NM, REGSTR_KD_CD, REGSTR_KD_NM
       , PLOT_LOC, RDNM_PLOT_LOC, BULD_NM
       , ARCD, LEGCD, PLOT_GB_CD, BUN, JI, SP_PLOT_NM
       , BLOCK, LOT, OUT_LOT_CO
       , NW_ADDR_ROAD_CD, NW_ADDR_LEG_CD, NW_ADDR_GRND_CD, NW_ADDR_MAIN_B, NW_ADDR_SUB_B
       , ZONE_CD, DISTRICT_CD, AREA_CD, ZONE_CD_NM, DISTRICT_CD_NM, AREA_CD_NM
       , CREAT_DE, BATCH_YN
) VALUES (
       #{mngrRegstrPk}, #{upperRegstrPk}, #{regstrGbCd}, #{regstrGbNm}, #{regstrKdCd}, #{regstrKdNm}
       , #{plotLoc}, #{rdnmPlotLoc}, #{buldNm}
       , #{arcd}, #{legcd}, #{plotGbCd}, #{bun}, #{ji}, #{spPlotNm}
       , #{block}, #{lot}, #{outLotCo}
       , #{nwAddrRoadCd}, #{nwAddrLegCd}, #{nwAddrGrndCd}, #{nwAddrMainB}, #{nwAddrSubB}
       , #{zoneCd}, #{districtCd}, #{areaCd}, #{zoneCdNm}, #{districtCdNm}, #{areaCdNm}
       , #{creatDe}, #{batchYn}
)

INSERT /* homes.batch.mapper.BatchMapper.insertPssionLedgr 전유부 등록 */
INTO   TB_BD_PSSION_LEDGR (
  BULD_REGSTR_PK, REGSTR_GB_CD, REGSTR_GB_NM, REGSTR_KD_CD, REGSTR_KD_NM, PLOT_LOC, RDNM_PLOT_LOC, BULD_NM
  , ARCD, LEGCD, PLOT_GB_CD, BUN, JI, SP_PLOT_NM, BLOCK, LOT
  , NW_ADDR_ROAD_CD, NW_ADDR_LEG_CD, NW_ADDR_GRND_CD, NW_ADDR_MAIN_B, NW_ADDR_SUB_B
  , BLOCK_NM, HO_NM, FLOOR_GB_CD, FLOOR_GB_NM, FLOOR_NO, CREAT_DE
) VALUES (
  #{buldRegstrPk}
  , #{regstrGbCd}
  , #{regstrGbNm}
  , #{regstrKdCd}
  , #{regstrKdNm}
  , #{plotLoc}
  , #{rdnmPloLoc}
  , #{buldNm}
  , #{arcd}
  , #{legcd}
  , #{plogGbCd}
  , #{bun}
  , #{ji}
  , #{spPlotNm}
  , #{block}
  , #{lot}
  , #{nwAddrRoadCd}
  , #{nwAddrLegCd}
  , #{nwAddrGrndCd}
  , #{nwAddrMainB}
  , #{nwAddrSubB}
  , #{blockNm}
  , #{hoNm}
  , #{floorGbCd}
  , #{floorGbNm}
  , #{floorNo}
  , #{creatDe}
)

	INSERT /* homes.batch.mapper.BatchMapper.insertBatchjob */ 
	INTO TB_CM_BATCHJOB (
		BT_UUID
		, BATCHTY
		, BT_STTUS_CD
        , BT_EXCO 
        , BT_FILENM 
		, BT_ERROR_MSG
		, BT_ST_DT
		, CREAT_USER_NO
		, CREAT_DT
		, UPDT_USER_NO
		, UPDT_DT
	) VALUES(
		#{uuid}
		, #{batchty}
		, #{sttuscd}
		, #{exco}
		, #{filenm}
		, #{message}
		, NOW()
		, #{mngrno}
		, NOW()
		, #{mngrno}
		, NOW()
	)

mapper.update:
UPDATE /* homes.batch.mapper.BatchMapper.updateBatchjob */ 
       TB_CM_BATCHJOB
SET    BT_STTUS_CD = #{sttuscd}
       , BT_ED_DT = NOW()
       , BT_EXCO = #{exco}
       , BT_FILENM = #{filenm}
       , BT_ERROR_MSG = #{message}
       , UPDT_USER_NO = #{mngrno} 
       , UPDT_DT = NOW()
WHERE  BT_UUID = #{uuid}

UPDATE /* homes.batch.mapper.BatchMapper.updatePssionLedger */ 
       TB_HBD_PSSION_BULD
SET    FLOOR_GB_CD      = #{floorGbCd}
       , FLOOR_GB_NM    = #{floorGbNm}
       , DONG_NM        = #{dongNm}
       , HO_NM          = #{hoNm}
       , FLOOR_NO       = #{floorNo}
       , CR_DE          = #{crde}
       , UPDT_USER_NO   = #{mngrno}
       , UPDT_DT        = NOW() 
WHERE  BULD_REGSTR_PK   = #{buldRegstrPk}

